steps.solution:
var position = Vector2(300, 0)
var speed = 150
var walking = Vector2(0, 0)
var facing = "right"

func move(direction, delta):
	position += direction * speed * delta
	if position.x < 0:
		position.x = 0
	if position.x > 600:
		position.x = 600

func go_left():
	walking = Vector2(-1, 0)
	facing = "left"

func go_right():
	walking = Vector2(1, 0)
	facing = "right"

func stop():
	walking = Vector2(0, 0)

func _process(delta):
	move(walking, delta)
